import assert from 'node:assert/strict';
import {setImmediate} from 'node:timers/promises';
import test from 'node:test';
import {createBalanceClient} from './src/client.mjs';
import {singleFlight} from './src/pending.mjs';
import {resolveBalance} from './src/resolve.mjs';

function deferred() {
  let resolve;
  let reject;
  const promise = new Promise((yes, no) => {
    resolve = yes;
    reject = no;
  });
  return {promise, resolve, reject};
}

test('the same ordered pair shares one pending Promise and original arguments', async () => {
  const gate = deferred();
  const calls = [];
  const client = createBalanceClient((...args) => {
    calls.push(args);
    return gate.promise;
  });
  const first = client(' Tenant:Ω ', 'Account:001');
  const second = client(' Tenant:Ω ', 'Account:001');
  assert.ok(first instanceof Promise);
  assert.strictEqual(first, second);
  const value = {balanceMinor: 0, currency: 'JPY'};
  gate.resolve(value);
  assert.strictEqual(await first, value);
  assert.deepEqual(calls, [[' Tenant:Ω ', 'Account:001']]);
});

test('different ordered pairs stay independent, including tenant and delimiter collisions', async () => {
  const pairs = [
    ['tenant-a', 'shared-account'],
    ['tenant-b', 'shared-account'],
    ['tenant-a', 'other-account'],
    ['a:b', 'c'],
    ['a', 'b:c'],
    ['left', 'right'],
    ['right', 'left'],
    ['', ':'],
    [':', ''],
    ['__proto__', 'constructor'],
    ['quote"', 'slash\\'],
  ];
  const gates = pairs.map(() => deferred());
  const calls = [];
  const client = createBalanceClient((tenant, account) => {
    calls.push([tenant, account]);
    return gates[pairs.findIndex(pair => pair[0] === tenant && pair[1] === account)].promise;
  });
  const requests = pairs.map(pair => client(...pair));
  assert.equal(new Set(requests).size, pairs.length);
  for (let i = 0; i < pairs.length; i++) {
    assert.strictEqual(client(...pairs[i]), requests[i]);
    gates[i].resolve({balanceMinor: i, currency: `currency-${i}`});
  }
  assert.deepEqual(await Promise.all(requests), pairs.map((_, i) => ({
    balanceMinor: i, currency: `currency-${i}`,
  })));
  assert.deepEqual(calls, pairs);
});

test('fulfillment clears the entry and later requests load fresh values', async () => {
  let calls = 0;
  const client = createBalanceClient(() => Promise.resolve(++calls));
  const first = client('t', 'a');
  assert.equal(await first, 1);
  const second = client('t', 'a');
  assert.notStrictEqual(first, second);
  assert.strictEqual(second, client('t', 'a'));
  assert.equal(await second, 2);
  assert.equal(await client('t', 'a'), 3);
});

test('plain return values are wrapped and shared only while pending', async () => {
  let calls = 0;
  const client = createBalanceClient(() => ++calls);
  const first = client('t', 'a');
  assert.ok(first instanceof Promise);
  assert.strictEqual(first, client('t', 'a'));
  assert.equal(await first, 1);
  assert.equal(await client('t', 'a'), 2);
});

test('rejection preserves the reason, clears the entry, and has no extra unhandled rejection', async () => {
  const gate = deferred();
  const failure = new Error('load failed');
  let calls = 0;
  const client = createBalanceClient(() => ++calls === 1 ? gate.promise : 42);
  const first = client('t', 'a');
  assert.strictEqual(first, client('t', 'a'));
  const rejected = assert.rejects(first, error => error === failure);
  gate.reject(failure);
  await rejected;
  const retry = client('t', 'a');
  assert.notStrictEqual(retry, first);
  assert.equal(await retry, 42);
  assert.equal(calls, 2);
  // Let Node report any orphan rejection created by a cleanup handler.
  await setImmediate();
});

test('synchronous throws become shared rejected Promises and allow retries', async () => {
  const failure = new Error('synchronous failure');
  let calls = 0;
  const client = createBalanceClient(() => {
    if (++calls === 1) throw failure;
    return 0;
  });
  let first;
  assert.doesNotThrow(() => { first = client('t', 'a'); });
  assert.ok(first instanceof Promise);
  assert.strictEqual(first, client('t', 'a'));
  await assert.rejects(first, error => error === failure);
  assert.equal(await client('t', 'a'), 0);
  assert.equal(calls, 2);
  await setImmediate();
});

test('settling one tenant does not clear another tenant’s pending request', async () => {
  const gates = [deferred(), deferred()];
  let calls = 0;
  const client = createBalanceClient(() => gates[calls++].promise);
  const first = client('one', 'shared');
  const second = client('two', 'shared');
  gates[0].resolve(10);
  assert.equal(await first, 10);
  assert.strictEqual(client('two', 'shared'), second);
  gates[1].resolve(20);
  assert.equal(await second, 20);
  assert.equal(calls, 2);
});

test('singleFlight preserves its exported key-and-arguments interface', async () => {
  const calls = [];
  const get = singleFlight((...args) => {
    calls.push(args);
    return args;
  });
  const key = {};
  const first = get(key, 'tenant', 'account');
  assert.strictEqual(first, get(key, 'ignored-while-pending'));
  const other = get({}, 'other');
  assert.notStrictEqual(first, other);
  assert.deepEqual(await first, ['tenant', 'account']);
  assert.deepEqual(await other, ['other']);
  assert.deepEqual(await get(key, 'fresh'), ['fresh']);
  assert.deepEqual(calls, [['tenant', 'account'], ['other'], ['fresh']]);
});

for (const [balanceMinor, currency] of [
  [0, 'JPY'],
  [-150, 'EUR'],
  [12345, 'KWD'],
  [Number.MAX_SAFE_INTEGER, 'CHF'],
  [Number.MIN_SAFE_INTEGER, 'GBP'],
]) {
  test(`resolveBalance preserves ${balanceMinor} minor units and ${currency}`, async () => {
    const value = Object.freeze({balanceMinor, currency});
    const client = createBalanceClient(() => value);
    assert.deepEqual(await resolveBalance(client, 'tenant:Ω', 'account:001'), {
      tenant: 'tenant:Ω', account: 'account:001', balanceMinor, currency,
    });
  });
}

test('resolveBalance propagates the original load failure', async () => {
  const failure = new Error('balance unavailable');
  const client = createBalanceClient(() => Promise.reject(failure));
  await assert.rejects(resolveBalance(client, 't', 'a'), error => error === failure);
  await setImmediate();
});

