import assert from 'node:assert/strict';
import test from 'node:test';
import {createBalanceClient} from './src/client.mjs';
import {singleFlight} from './src/pending.mjs';
import {resolveBalance} from './src/resolve.mjs';

function deferred() {
  let resolve, reject;
  const promise = new Promise((yes, no) => { resolve = yes; reject = no; });
  return {promise, resolve, reject};
}

test('identical pairs share the exact pending Promise and reload after fulfillment', async () => {
  const calls = [];
  const first = deferred();
  const value = {balanceMinor: 42, currency: 'EUR'};
  const client = createBalanceClient((...args) => {
    calls.push(args);
    return calls.length === 1 ? first.promise : value;
  });
  const pending = client('tenant', 'account');
  assert.ok(pending instanceof Promise);
  assert.strictEqual(client('tenant', 'account'), pending);
  await Promise.resolve();
  assert.deepEqual(calls, [['tenant', 'account']]);
  first.resolve(value);
  assert.strictEqual(await pending, value);
  const next = client('tenant', 'account');
  assert.notStrictEqual(next, pending);
  assert.strictEqual(await next, value);
  assert.equal(calls.length, 2);
});

test('ordered pairs remain isolated across tenants, accounts and delimiter collisions', async () => {
  const pairs = [
    ['tenant-1', 'shared'], ['tenant-2', 'shared'],
    ['tenant-1', 'other'], ['a:b', 'c'], ['a', 'b:c'],
    ['left', 'right'], ['right', 'left'], ['', ':'], [':', ''],
    ['a\",\"b', 'c'], ['a', 'b\",\"c'],
  ];
  const calls = [];
  const gates = pairs.map(() => deferred());
  const client = createBalanceClient((...args) => {
    calls.push(args);
    return gates[pairs.findIndex(pair => pair[0] === args[0] && pair[1] === args[1])].promise;
  });
  const promises = pairs.map(pair => client(...pair));
  assert.equal(new Set(promises).size, pairs.length);
  pairs.forEach((pair, i) => assert.strictEqual(client(...pair), promises[i]));
  await Promise.resolve();
  assert.deepEqual(calls, pairs);
  const values = pairs.map((_, i) => ({balanceMinor: i - 5, currency: "'`currency-${i}`}));
  gates.forEach((gate, i) => gate.resolve(values[i]));
  assert.deepEqual(await Promise.all(promises), values);
});

for (const mode of ['"'asynchronous rejection', 'synchronous throw']) {
  test("'`${mode} propagates unchanged, clears pending, and has no extra unhandled rejection`, async () => {
    const failure = new Error(mode);
    const gate = deferred();
    let calls = 0;
    const client = createBalanceClient(() => {
      calls++;
      if (calls > 1) return {balanceMinor: 0, currency: '"'JPY'};
      if (mode === 'synchronous throw') throw failure;
      return gate.promise;
    });
    let pending;
    assert.doesNotThrow(() => { pending = client('t', 'a'); });
    assert.ok(pending instanceof Promise);
    assert.strictEqual(client('t', 'a'), pending);
    const checked = assert.rejects(pending, error => error === failure);
    if (mode === 'asynchronous rejection') gate.reject(failure);
    await checked;
    const retry = client('t', 'a');
    assert.notStrictEqual(retry, pending);
    assert.deepEqual(await retry, {balanceMinor: 0, currency: 'JPY'});
    assert.equal(calls, 2);
    // Let unhandled-rejection events fire; node:test fails on any such event.
    await new Promise(resolve => setImmediate(resolve));
  });
}

test('plain values always produce Promises and are not persisted', async () => {
  let calls = 0;
  const client = createBalanceClient(() => ++calls);
  for (let expected = 1; expected <= 3; expected++) {
    const pending = client('t', 'a');
    assert.ok(pending instanceof Promise);
    assert.equal(await pending, expected);
  }
});

test('singleFlight export forwards loader arguments without its cache key', async () => {
  const calls = [];
  const get = singleFlight((...args) => { calls.push(args); return args; });
  const pending = get('key', 'tenant', 'account');
  assert.strictEqual(get('key', 'ignored'), pending);
  assert.deepEqual(await pending, ['tenant', 'account']);
  assert.deepEqual(calls, [['tenant', 'account']]);
});

test('resolver preserves minor units and currency exactly', async () => {
  for (const balanceMinor of [0, -0, -125, 12345, Number.MAX_SAFE_INTEGER, Number.MIN_SAFE_INTEGER]) {
    for (const currency of ['EUR', 'JPY', 'KWD']) {
      const client = createBalanceClient(() => ({balanceMinor, currency}));
      assert.deepEqual(await resolveBalance(client, 'original tenant', 'original account'), {
        tenant: 'original tenant', account: 'original account', balanceMinor, currency,
      });
    }
  }
});

test('resolver propagates loader failure without a fallback balance', async () => {
  const failure = new Error('lookup failed');
  await assert.rejects(resolveBalance(createBalanceClient(() => { throw failure; }), 't', 'a'),
    error => error === failure);
});
