export function singleFlight(load) {
  const pending = new Map();
  return (key, ...args) => {
    if (pending.has(key)) return pending.get(key);

    // Defer invocation so synchronous throws become rejections and the entry
    // exists before the loader runs. Keep this function non-async for identity.
    const promise = Promise.resolve().then(() => load(...args));
    pending.set(key, promise);
    const clear = () => { pending.delete(key); };
    // Handle both outcomes: a fulfillment-only handler creates an extra,
    // unhandled rejected promise when the loader fails.
    promise.then(clear, clear);
    return promise;
  };
}

