import assert from 'node:assert/strict';
import {setImmediate} from 'node:timers/promises';
import test from 'node:test';
import {createBalanceClient} from './src/client.mjs';
import {singleFlight} from './src/pending.mjs';
import {resolveBalance} from './src/resolve.mjs';

function deferred() {
  let resolve;
  let reject;
  const promise = new Promise((yes, no) => {
    resolve = yes;
    reject = no;
  });
  return {promise, resolve, reject};
}

test('same pair shares the identical pending Promise, then reloads', async () => {
  const first = deferred();
  const calls = [];
  const client = createBalanceClient((...args) => {
    calls.push(args);
    return calls.length === 1 ? first.promise : {balanceMinor: 2, currency: 'EUR'};
  });
  const pending = client('tenant', 'account');
  assert.ok(pending instanceof Promise);
  assert.strictEqual(client('tenant', 'account'), pending);
  await Promise.resolve();
  assert.deepEqual(calls, [['tenant', 'account']]);
  const initial = {balanceMinor: 1, currency: 'EUR'};
  first.resolve(initial);
  assert.strictEqual(await pending, initial);

  const next = client('tenant', 'account');
  assert.notStrictEqual(next, pending);
  assert.strictEqual(client('tenant', 'account'), next);
  assert.deepEqual(await next, {balanceMinor: 2, currency: 'EUR'});
  assert.equal(calls.length, 2);
});

test('ordered pairs are isolated and original strings reach the loader', async () => {
  const pairs = [
    ['tenant-a', 'shared'], ['tenant-b', 'shared'],
    ['a:b', 'c'], ['a', 'b:c'], ['c', 'a:b'],
    ['', ':'], [':', ''], ['', ''],
    ['tenant-a', 'other'], ['["a"]', 'b\\c'],
  ];
  const gates = pairs.map(() => deferred());
  const calls = [];
  const client = createBalanceClient((tenant, account) => {
    calls.push([tenant, account]);
    const index = pairs.findIndex(([t, a]) => t === tenant && a === account);
    return gates[index].promise;
  });
  const promises = pairs.map(pair => client(...pair));
  assert.equal(new Set(promises).size, pairs.length);
  pairs.forEach((pair, i) => assert.strictEqual(client(...pair), promises[i]));
  await Promise.resolve();
  assert.deepEqual(calls, pairs);
  // Settling one pair must leave every other pair pending and shared.
  gates[0].resolve(0);
  assert.equal(await promises[0], 0);
  pairs.slice(1).forEach((pair, i) => {
    assert.strictEqual(client(...pair), promises[i + 1]);
    gates[i + 1].resolve(i + 1);
  });
  assert.deepEqual(await Promise.all(promises), pairs.map((_, i) => i));
});

test('plain return values are promised, shared while pending, and never cached', async () => {
  let calls = 0;
  const client = createBalanceClient(() => ++calls);
  const first = client('t', 'a');
  assert.ok(first instanceof Promise);
  assert.strictEqual(client('t', 'a'), first);
  assert.equal(await first, 1);
  assert.equal(await client('t', 'a'), 2);
  assert.equal(await client('t', 'a'), 3);
});

for (const failure of ['rejection', 'synchronous throw']) {
  test(`${failure} is shared, preserves the error, clears pending, and adds no unhandled rejection`, async () => {
    const error = new Error(failure);
    let calls = 0;
    const client = createBalanceClient(() => {
      calls++;
      if (calls > 1) return {balanceMinor: -5, currency: 'GBP'};
      if (failure === 'synchronous throw') throw error;
      return Promise.reject(error);
    });
    let pending;
    assert.doesNotThrow(() => { pending = client('t', 'a'); });
    assert.ok(pending instanceof Promise);
    assert.strictEqual(client('t', 'a'), pending);
    await assert.rejects(pending, reason => reason === error);
    const retry = client('t', 'a');
    assert.notStrictEqual(retry, pending);
    assert.deepEqual(await retry, {balanceMinor: -5, currency: 'GBP'});
    assert.equal(calls, 2);
    // Allow any orphaned cleanup rejection to surface in the test runner.
    await setImmediate();
  });
}

test('singleFlight preserves its exported keyed interface and loader arguments', async () => {
  const gate = deferred();
  const calls = [];
  const get = singleFlight((...args) => {
    calls.push(args);
    return gate.promise;
  });
  const first = get('key', 'tenant', 'account');
  assert.strictEqual(get('key', 'ignored'), first);
  const other = get('other', 'another', 'account');
  assert.notStrictEqual(first, other);
  await Promise.resolve();
  assert.deepEqual(calls, [['tenant', 'account'], ['another', 'account']]);
  gate.resolve(7);
  assert.deepEqual(await Promise.all([first, other]), [7, 7]);
});

test('resolveBalance preserves zero, negative and large integer minor units and currency', async () => {
  const values = [
    {balanceMinor: 0, currency: 'EUR'},
    {balanceMinor: -12345, currency: 'JPY'},
    {balanceMinor: Number.MAX_SAFE_INTEGER, currency: 'KWD'},
    {balanceMinor: -Number.MAX_SAFE_INTEGER, currency: 'GBP'},
  ];
  for (const value of values) {
    const result = await resolveBalance(createBalanceClient(() => value), 'tenant', 'account');
    assert.deepEqual(result, {tenant: 'tenant', account: 'account', ...value});
  }
});

test('resolveBalance propagates the original loader error', async () => {
  const error = new Error('balance unavailable');
  const client = createBalanceClient(() => Promise.reject(error));
  await assert.rejects(resolveBalance(client, 't', 'a'), reason => reason === error);
  await setImmediate();
});

